from datetime import datetime
from decimal import Decimal, ROUND_HALF_UP


def to_iso(yyyymmdd: str | None) -> str | None:
    """Convert a legacy YYYYMMDD date to ISO format, mapping null sentinels to None."""
    if yyyymmdd is None or yyyymmdd == "" or yyyymmdd == "00000000":
        return None

    return datetime.strptime(yyyymmdd, "%Y%m%d").date().isoformat()


def from_iso(iso: str | None) -> str:
    """Convert an ISO date to legacy YYYYMMDD format, using the null sentinel."""
    if iso is None or iso == "":
        return "00000000"

    return datetime.strptime(iso, "%Y-%m-%d").strftime("%Y%m%d")


def yn(char: str | None) -> bool:
    """Convert the legacy Y/N convention to a boolean."""
    return char == "Y"


def to_minor_units(amount, currency: str | None) -> int:
    """Convert a decimal amount to currency minor units using half-up rounding."""
    if amount is None or (isinstance(amount, str) and amount.strip() == ""):
        return 0

    normalized_currency = (currency or "USD").strip().upper() or "USD"
    exponent = 0 if normalized_currency == "JPY" else 2
    scaled = Decimal(str(amount)) * (Decimal(10) ** exponent)

    return int(scaled.quantize(Decimal("1"), rounding=ROUND_HALF_UP))
